import unittest
from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.emoticon'
@points('1.emoticon')
class EmoticonTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_print_emoticon(self):
        reload_module(self.module)
        output = get_stdout()
        self.assertTrue(output.startswith(":"), "Make sure that you don't print out extra characters before the emoticon starts. | Asegúrate de no imprimir caracteres extra antes de que empiece el emoticono. | Ziurtatu ez duzula karaktere gehigarririk inprimatzen emotikonoa hasi aurretik.")
        self.assertTrue(output.endswith(""), "Make sure that you don't print out extra characters after the emoticon ends. | Asegúrate de no imprimir caracteres extra después de que termine el emoticono. | Ziurtatu ez duzula karaktere gehigarririk inprimatzen emotikonoa amaitu ondoren.")
        self.assertEqual(output, ":-)", "Emoticon is malformed. | El emoticono está mal formado. | Emotikonoa gaizki osatuta dago.")

import unittest
from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.seven_brothers'
@points('1.seven_brothers')
class SevenBrothersTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_content(self):
        reload_module(self.module)
        split_output = get_stdout().split('\\n')
        self.assertEqual(len(split_output), 7, 'Output was expected to have 7 lines, your program\'s output is now in {1} lines. | Se esperaba que la salida tuviera 7 líneas, pero tu programa produjo {1} líneas. | Irteerak 7 lerro izatea espero zen, baina zure programak {1} lerro sortu ditu.')
        correct = "Alsasua Baztan Estella Olite Pamplona Tafalla Tudela".split()
        for i in range(7):
            self.assertEqual(split_output[i], correct[i], "Line {0} in output is incorrect. | La línea {0} en la salida es incorrecta. | Irteerako {0} lerroa okerra da.".format(i + 1))

import unittest
from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.minutes_in_a_year'
@points('1.minutes_in_a_year')
class MinutesInAYearTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_output(self):
        reload_module(self.module)
        output = get_stdout()
        self.assertTrue(output.find("525600") > -1, "Output does not contain correct amount of minutes. | La salida no contiene la cantidad correcta de minutos. | Irteerak ez dauka minutu kopuru zuzena.")

import unittest
from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.print_code'
@points('1.print_code')
class PrintCodeTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_module(exercise, 'en')

    def test_output(self):
        reload_module(self.module)
        output = get_stdout()
        self.assertFalse(len(output) == 0, "Your code does not print anything :( | Tu código no imprime nada :( | Zure kodeak ez du ezer inprimatzen :(")
        self.assertTrue(output.count('print') == 1, "Output is missing print command. | Falta el comando print en la salida. | Print komandoa falta da irteeran.")
